import{_ as a,c as e,o as n,ae as r}from"./chunks/framework.Bi6zybwU.js";const d=JSON.parse('{"title":"Ninja Charts Integration","description":"Ninja Charts Integration","frontmatter":{"title":"Ninja Charts Integration","description":"Ninja Charts Integration"},"headers":[],"relativePath":"guide/data-sources/ninja-charts-integration.md","filePath":"guide/data-sources/ninja-charts-integration.md"}'),o={name:"guide/data-sources/ninja-charts-integration.md"};function s(i,t,h,l,c,g){return n(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ninja-charts-integration" tabindex="-1">Ninja Charts Integration <a class="header-anchor" href="#ninja-charts-integration" aria-label="Permalink to &quot;Ninja Charts Integration&quot;">​</a></h1><p>Ninja Charts has incredible features that generate endless online charts and graphs on your web pages. One of the great characteristics of <strong>Ninja Charts</strong> is the default functionality with <strong>Ninja Tables</strong>. With this WordPress charts plugin, you can create dynamic charts utilizing data from the Ninja Tables plugin. You can also pull data from Fluent Forms to create charts or manually input chart entries.</p><h2 id="create-a-chart" tabindex="-1">Create a Chart <a class="header-anchor" href="#create-a-chart" aria-label="Permalink to &quot;Create a Chart&quot;">​</a></h2><p>Let&#39;s have a look at the simple steps to learn how to create **Ninja Charts **with Ninja Tables. *****Ninja Charts **is a completely free charts plugin. You can use it with or without Ninja Tables in your dashboard.</p><ul><li>First, go to the <strong>Ninja Tables dashboard</strong> <strong>→</strong> <strong>Add Charts</strong> <strong>→</strong> <strong>Chart List</strong> &amp; then <strong>click</strong> on the **Create a new chart **button. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-Chart-E-5.png" alt="Create a New Chart"></li><li>Put your** Chart Name** in the title <strong>→</strong> choose a <strong>Chart</strong> to <strong>Renderer</strong> engine <strong>→</strong> select your preferred <strong>Chart</strong> <strong>Type</strong> from the dashboard <strong>→</strong> then click on the <strong>Next</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2023/07/Ninja-Charts-chart-types-1024x560.png" alt="Ninja Charts chart types"></li><li>From the <strong>Source,</strong> select <strong>Ninja Tables</strong>/<strong>Fluent Forms</strong> or <strong>Manual Input</strong>.</li></ul><p>Choose the preferred data source (manual, forms, or tables) you want to create a chart with from the Data field.</p><ul><li>Then click on the** Next** button [In this step, you will also have an option for manual chart creation] <img src="https://ninjatables.com/wp-content/uploads/2023/03/Ninja-Charts-from-Ninja-Tables-and-Fluent-Forms-1-1024x413.png" alt="Ninja Charts from Ninja Tables and Fluent Forms"></li><li>Then, you’ll get the option to drag &amp; drop the desired <strong>columns</strong> and click on the <strong>Next</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-Chart-GIF.gif" alt="Create using Ninja-Charts"></li><li>Following that, you will see the prepared chart with <strong>Formatting &amp; preview</strong> options. When you&#39;ve finished making the necessary changes, click the <strong>Next</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-Chart-E-3-1024x496.png" alt="edit wordpress charts"></li><li>Once you click on the <strong>Next</strong> button, you&#39;ll move to the &quot;<strong>Save &amp; Get Shortcode</strong>&quot; window. Copy the auto-generated shortcode and paste it anywhere on your website.</li></ul><h2 id="wordpress-charts-demo-ninja-charts" tabindex="-1">WordPress Charts Demo - Ninja Charts <a class="header-anchor" href="#wordpress-charts-demo-ninja-charts" aria-label="Permalink to &quot;WordPress Charts Demo - Ninja Charts&quot;">​</a></h2><p>Pie Chart: [ninja_charts id=&quot;6&quot;] Line Chart: [ninja_charts id=&quot;3&quot;] These processes are simple and less time-consuming. As a result, you won&#39;t find it difficult to build sophisticated or even enormous charts/graphs.</p>',9)])])}const p=a(o,[["render",s]]);export{d as __pageData,p as default};
